use clap::Parser;
#[derive(Parser)]
struct Args { #[arg(long,default_value="http://127.0.0.1:3000")] server: String, #[arg(long)] json: bool }
#[tokio::main]
async fn main() {
 let a = Args::parse();
 match reqwest::Client::new().get(format!("{}/health",a.server)).send().await {
  Ok(r) if r.status().is_success() => println!("{}",r.text().await.unwrap()),
  _ => std::process::exit(1),
 }
}

//! Shared Depot types and validation.
mod model;
pub use model::*;

use serde::{Deserialize, Serialize};
#[derive(Debug, thiserror::Error)]
#[error("{0}")]
pub struct Invalid(pub String);
pub fn identifier(value: &str) -> Result<(), Invalid> {
    if value.is_empty() || value.len() > 64 || !value.as_bytes()[0].is_ascii_alphanumeric()
        || !value.bytes().all(|c| c.is_ascii_alphanumeric() || b"._-".contains(&c)) {
        return Err(Invalid("identifier must be 1–64 ASCII letters/digits/dot/underscore/hyphen, starting alphanumeric".into()));
    }
    Ok(())
}
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Repository { pub name: String, pub description: String, pub created: u64 }
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Artifact { pub repository: String, pub name: String, pub version: String, pub size: u64, pub sha256: String, pub content_type: String, pub created: u64 }
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all="camelCase")]
pub struct Page<T> { pub items: Vec<T>, pub page: u64, pub page_size: u64, pub total: u64 }
pub fn pagination(page: Option<&str>, size: Option<&str>) -> Result<(u64,u64), Invalid> {
    let p = page.unwrap_or("1").parse::<u64>().map_err(|_| Invalid("invalid page".into()))?;
    let s = size.unwrap_or("20").parse::<u64>().map_err(|_| Invalid("invalid pageSize".into()))?;
    if p == 0 || s == 0 || s > 100 || p.checked_mul(s).is_none() { return Err(Invalid("pagination outside supported range".into())); }
    Ok((p,s))
}

use depot_domain::{identifier,pagination};
#[test] fn identifiers_and_pages() {
 for good in ["A","opaque_1.2-3"] { assert!(identifier(good).is_ok()); }
 for bad in ["",".","..","../x","a/b","é","_a"] { assert!(identifier(bad).is_err()); }
 assert_eq!(pagination(None,None).unwrap(),(1,20));
 for v in ["0","-1","1.5","101"] { assert!(pagination(None,Some(v)).is_err()); }
}

use axum::{routing::get,Json,Router};
#[tokio::main]
async fn main() {
 let addr = std::env::var("DEPOT_LISTEN").unwrap_or("127.0.0.1:3000".into());
 let listener = tokio::net::TcpListener::bind(&addr).await.expect("listen");
 println!("LISTEN {}",listener.local_addr().unwrap());
 let app = Router::new().route("/health",get(|| async { Json(serde_json::json!({"status":"ok"})) }));
 axum::serve(listener,app).with_graceful_shutdown(async { let _ = tokio::signal::ctrl_c().await; }).await.unwrap();
}
